// ============================================================
//  Ballpit.jsx — Fixed & Optimized for your portfolio
// ============================================================

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';

class ThreeScene {
  canvas;
  camera;
  scene;
  renderer;
  size = { width: 0, height: 0, wWidth: 0, wHeight: 0 };
  isDisposed = false;

  constructor(canvas) {
    this.canvas = canvas;
    this.#init();
  }

  #init() {
    this.camera = new THREE.PerspectiveCamera(50, 1, 0.1, 100);
    this.camera.position.set(0, 0, 22);

    this.scene = new THREE.Scene();

    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      alpha: true,
      powerPreference: 'high-performance'
    });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
  }

  resize() {
    const rect = this.canvas.parentElement.getBoundingClientRect();
    this.size.width = rect.width;
    this.size.height = rect.height;

    this.camera.aspect = this.size.width / this.size.height;
    this.camera.updateProjectionMatrix();

    this.renderer.setSize(this.size.width, this.size.height);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    // Update world size
    const fovRad = (this.camera.fov * Math.PI) / 180;
    this.size.wHeight = 2 * Math.tan(fovRad / 2) * this.camera.position.z;
    this.size.wWidth = this.size.wHeight * this.camera.aspect;
  }

  render = () => {
    this.renderer.render(this.scene, this.camera);
  };

  clear() {
    this.scene.traverse((object) => {
      if (object.isMesh) {
        object.geometry?.dispose();
        if (object.material) {
          if (Array.isArray(object.material)) {
            object.material.forEach(m => m.dispose());
          } else {
            object.material.dispose();
          }
        }
      }
    });
    this.scene.clear();
  }

  dispose() {
    if (this.isDisposed) return;
    this.clear();
    this.renderer.dispose();
    this.isDisposed = true;
  }
}

// Ball Physics
class BallPhysics {
  constructor(config) {
    this.config = config;
    this.positions = new Float32Array(3 * config.count);
    this.velocities = new Float32Array(3 * config.count);
    this.sizes = new Float32Array(config.count);
    this.#init();
  }

  #init() {
    const { count, maxX, maxY, maxZ, minSize, maxSize } = this.config;
    for (let i = 0; i < count; i++) {
      const idx = i * 3;
      this.positions[idx]     = THREE.MathUtils.randFloatSpread(maxX * 2);
      this.positions[idx + 1] = THREE.MathUtils.randFloatSpread(maxY * 2);
      this.positions[idx + 2] = THREE.MathUtils.randFloatSpread(maxZ * 2);

      this.velocities[idx] = THREE.MathUtils.randFloatSpread(0.8);
      this.velocities[idx + 1] = THREE.MathUtils.randFloatSpread(0.8);
      this.velocities[idx + 2] = THREE.MathUtils.randFloatSpread(0.8);

      this.sizes[i] = THREE.MathUtils.randFloat(minSize, maxSize);
    }
  }

  update(delta) {
    const { count, gravity, friction, wallBounce, maxX, maxY, maxZ } = this.config;

    for (let i = 0; i < count; i++) {
      const idx = i * 3;

      // Apply gravity
      this.velocities[idx + 1] -= gravity * delta * 60;

      // Friction
      this.velocities[idx] *= friction;
      this.velocities[idx + 1] *= friction;
      this.velocities[idx + 2] *= friction;

      // Update position
      this.positions[idx]     += this.velocities[idx] * delta * 60;
      this.positions[idx + 1] += this.velocities[idx + 1] * delta * 60;
      this.positions[idx + 2] += this.velocities[idx + 2] * delta * 60;

      const radius = this.sizes[i];

      // Wall collisions
      if (Math.abs(this.positions[idx]) + radius > maxX) {
        this.positions[idx] = Math.sign(this.positions[idx]) * (maxX - radius);
        this.velocities[idx] *= -wallBounce;
      }
      if (this.positions[idx + 1] - radius < -maxY) {
        this.positions[idx + 1] = -maxY + radius;
        this.velocities[idx + 1] *= -wallBounce;
      }
      if (Math.abs(this.positions[idx + 2]) + radius > maxZ) {
        this.positions[idx + 2] = Math.sign(this.positions[idx + 2]) * (maxZ - radius);
        this.velocities[idx + 2] *= -wallBounce;
      }
    }
  }
}

// Main Ballpit Component
const Ballpit = ({
  count = 70,
  gravity = 0.1,
  friction = 0.985,
  wallBounce = 0.9,
  followCursor = true,
}) => {
  const canvasRef = useRef(null);
  const sceneRef = useRef(null);
  const ballsRef = useRef(null);
  const animationRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const three = new ThreeScene(canvas);
    sceneRef.current = three;

    const physics = new BallPhysics({
      count,
      gravity,
      friction,
      wallBounce,
      maxX: 12,
      maxY: 8,
      maxZ: 5,
      minSize: 0.6,
      maxSize: 1.5,
    });

    // Create Instanced Mesh
    const geometry = new THREE.SphereGeometry(1, 32, 32);
    const material = new THREE.MeshPhysicalMaterial({
      color: 0x3b82f6,
      metalness: 0.7,
      roughness: 0.3,
      clearcoat: 1.0,
      clearcoatRoughness: 0.1,
      envMapIntensity: 1.0,
    });

    const instancedMesh = new THREE.InstancedMesh(geometry, material, count);
    const dummy = new THREE.Object3D();

    // Lights
    const ambient = new THREE.AmbientLight(0xffffff, 0.6);
    const pointLight = new THREE.PointLight(0x60a5fa, 2, 100);
    three.scene.add(ambient, pointLight, instancedMesh);

    ballsRef.current = { instancedMesh, dummy, physics, pointLight };

    // Animation loop
    let lastTime = 0;
    const animate = (time) => {
      animationRef.current = requestAnimationFrame(animate);
      const delta = Math.min((time - lastTime) / 1000, 0.1);
      lastTime = time;

      physics.update(delta);

      for (let i = 0; i < count; i++) {
        const idx = i * 3;
        dummy.position.set(
          physics.positions[idx],
          physics.positions[idx + 1],
          physics.positions[idx + 2]
        );
        dummy.scale.setScalar(physics.sizes[i]);
        dummy.updateMatrix();
        instancedMesh.setMatrixAt(i, dummy.matrix);
      }

      if (i === 0) pointLight.position.set(physics.positions[0], physics.positions[1], physics.positions[2]);

      instancedMesh.instanceMatrix.needsUpdate = true;
      three.render();
    };

    three.resize();
    animate(0);

    // Cleanup
    return () => {
      cancelAnimationFrame(animationRef.current);
      three.dispose();
    };
  }, [count, gravity, friction, wallBounce]);

  return (
    <canvas
      ref={canvasRef}
      className="hero__ballpit"
      style={{ width: '100%', height: '100%' }}
    />
  );
};

export default Ballpit;
